{"file_text": "from app.api.handlers import handle_get_user, handle_create_user


def test_get_user_ok():
    assert handle_get_user({"id": "1"}) == (200, {"id": 1, "name": "Ada", "email": "ada@example.com"})


def test_get_user_invalid():
    assert handle_get_user({"id": "abc"})[0] == 400


def test_get_user_missing():
    assert handle_get_user({"id": "99"})[0] == 404


def test_create_user_ok():
    status, user = handle_create_user({"name": " John ", "email": "john@example.com"})
    assert status == 201
    assert user["name"] == "John"
    assert user["email"] == "john@example.com"
    assert user["id"] > 0
    # verify retrieval
    assert handle_get_user({"id": str(user["id"])}) == (200, user)


def test_create_user_invalid_name():
    assert handle_create_user({"name": "", "email": "a@b.com"})[0] == 400
    assert handle_create_user({"name": "a" * 51, "email": "a@b.com"})[0] == 400


def test_create_user_invalid_email():
    assert handle_create_user({"name": "John", "email": "invalid"})[0] == 400


def test_create_user_duplicate_email():
    handle_create_user({"name": "John", "email": "john@duplicate.com"})
    assert handle_create_user({"name": "Jane", "email": "john@duplicate.com"})[0] == 409
